"use strict";
// One-off page: sends exactly two fixed transactions (timelock scheduleBatch on BSC and on WANTOS). No inputs, no network
// calls of its own: everything goes through the wallet's provider.
const ADMIN = "0x860f5B29f60F86c82b18f789E0219Cf966375669".toLowerCase();
const TIMELOCK = "0xE962600e3F9c608Cf7E0e80aB450ffE63b563618";
const JOBS = {
  bsc: {
    chainId: "0x38",
    name: "BNB Smart Chain",
    id: "0x10868fc9571a399a12b30d117f6af6f1b844d1077266a7540c25284009a7457b",
    data: "",
  },
  wantos: {
    chainId: "0x34f3",
    name: "WANTOS",
    id: "0x0c755dfaefab596b0983c5343282c7d0d47683a97ed5c5c30b8032d021e98d8f",
    data: "",
    add: { chainId: "0x34f3", chainName: "WANTOS", nativeCurrency: { name: "WANT", symbol: "WANT", decimals: 18 }, rpcUrls: ["https://rpc.wantos.io"], blockExplorerUrls: ["https://scan.wantos.io"] },
  },
};
const SEL = { isOperation: "0x31d50750", getTimestamp: "0xd45c4435" };
let account = null;
const $ = (id) => document.getElementById(id);
const eth = () => window.ethereum;
const say = (id, msg, cls) => { const e = $(id); e.textContent = msg; e.className = "status " + (cls || ""); };

for (const k of Object.keys(JOBS)) $("raw-" + k).textContent = JOBS[k].data;

async function connect() {
  try {
    if (!eth()) return say("account", "没有检测到钱包。请在钱包 App 自带的浏览器里打开本页。", "err");
    const accs = await eth().request({ method: "eth_requestAccounts" });
    account = (accs[0] || "").toLowerCase();
    if (account !== ADMIN) {
      for (const k of Object.keys(JOBS)) $("send-" + k).disabled = true;
      return say("account", "连接的是 " + account + "，不是管理钱包 0x860f…5669。请在钱包里切换到管理钱包后再点一次。", "err");
    }
    say("account", "已连接管理钱包 " + account, "ok");
    for (const k of Object.keys(JOBS)) if (!JOBS[k].sent) $("send-" + k).disabled = false;
  } catch (e) { say("account", "连接失败：" + (e && e.message ? e.message : e), "err"); }
}

async function ensureChain(job) {
  const cur = await eth().request({ method: "eth_chainId" });
  if (String(cur).toLowerCase() === job.chainId) return;
  try {
    await eth().request({ method: "wallet_switchEthereumChain", params: [{ chainId: job.chainId }] });
  } catch (e) {
    if (job.add && e && (e.code === 4902 || e.code === -32603)) {
      await eth().request({ method: "wallet_addEthereumChain", params: [job.add] });
    } else throw e;
  }
  const now = await eth().request({ method: "eth_chainId" });
  if (String(now).toLowerCase() !== job.chainId) throw new Error("钱包没有切换到 " + job.name);
}

async function exists(job) {
  const r = await eth().request({ method: "eth_call", params: [{ to: TIMELOCK, data: SEL.isOperation + job.id.slice(2) }, "latest"] });
  return /1$/.test(String(r));
}

async function send(key) {
  const job = JOBS[key], out = "out-" + key, btn = $("send-" + key);
  try {
    if (account !== ADMIN) return say(out, "先连接管理钱包。", "err");
    btn.disabled = true;
    say(out, "正在切换网络…");
    await ensureChain(job);
    if (await exists(job)) { say(out, "这个提案已经在链上了，不用再发。", "ok"); return; }
    say(out, "请在钱包里确认这笔交易（交易数据与上面显示的一致）…");
    const hash = await eth().request({ method: "eth_sendTransaction", params: [{ from: account, to: TIMELOCK, data: job.data, value: "0x0" }] });
    job.sent = true;
    say(out, "已发送。交易哈希：" + hash + "  请把它发给 Claude。", "ok");
  } catch (e) {
    btn.disabled = false;
    say(out, "没有发出：" + (e && e.message ? e.message : e), "err");
  }
}

$("connect").addEventListener("click", connect);
$("send-bsc").addEventListener("click", () => send("bsc"));
$("send-wantos").addEventListener("click", () => send("wantos"));
